# ============================================================================
# TEST 1: ALL SERVICE HEALTH CHECKS
# ============================================================================
Write-Header "TEST 1: ALL SERVICE HEALTH CHECKS"

$services = @(
    @{ name="API Gateway";     url="$API_GATEWAY/health" },
    @{ name="Auth Service";    url="$AUTH_SERVICE/health" },
    @{ name="Fraud Service";   url="$FRAUD_SERVICE/health" },
    @{ name="Bank Connector";  url="$BANK_CONNECTOR/health" }
)

foreach ($svc in $services) {
    Write-Step "$($svc.name)"
    try {
        $h = Invoke-RestMethod -Uri $svc.url -Method GET -TimeoutSec 10
        if ($h.status -eq "ok") {
            Pass "$($svc.name) is healthy"

            # Bank connector extra info
            if ($svc.name -eq "Bank Connector") {
                if ($h.stripe_connected) {
                    Pass "Stripe API connected"
                    Info "Stripe Connected: $($h.stripe_connected)"
                } else {
                    Warn "Stripe not connected - check STRIPE_SECRET_KEY in .env"
                    Info "Tests will fail if Stripe key is placeholder"
                }
                foreach ($cb in $h.circuit_breakers.PSObject.Properties) {
                    Info "Circuit Breaker [$($cb.Name)]: $($cb.Value.state)"
                }
            }
        } else {
            Fail "$($svc.name) unhealthy"
        }
    } catch {
        Fail "$($svc.name) unreachable - is it running?"
        if ($svc.name -eq "Bank Connector") {
            Info "Check: docker-compose logs bank-connector"
            exit 1
        }
    }
}

