# ============================================================================
# TEST 6: DECLINED CARDS
# ============================================================================
Write-Header "TEST 6: DECLINED CARDS - ERROR HANDLING"

$declineTests = @(
    @{ name="Generic Decline";    number="4000000000000002" },
    @{ name="Insufficient Funds"; number="4000000000009995" },
    @{ name="Lost Card";          number="4000000000009987" },
    @{ name="Stolen Card";        number="4000000000009979" }
)

foreach ($test in $declineTests) {
    Write-Step "$($test.name) - $($test.number)"
    try {
        $declineBody = @{
            payment_id      = "pi_decline_$(Get-Date -Format 'yyyyMMddHHmmssff')"
            merchant_id     = "m_123"
            amount          = 5000
            currency        = "usd"
            idempotency_key = New-IKey
            card            = @{
                number    = $test.number
                exp_month = 12
                exp_year  = 2026
                cvc       = "123"
            }
        } | ConvertTo-Json

        Invoke-RestMethod -Uri "$BANK_CONNECTOR/authorize" `
            -Method POST -Body $declineBody -ContentType "application/json"

        Fail "$($test.name) should have been declined!"
    } catch {
        $statusCode = $_.Exception.Response.StatusCode.value__
        if ($statusCode -eq 402) {
            $e = Get-ErrorDetail $_
            Pass "$($test.name) declined correctly (402)"
            Info "Code: $($e.detail.code)"
            Info "Decline Code: $($e.detail.decline_code)"
            Info "Message: $($e.detail.message)"
        } else {
            Pass "$($test.name) rejected (HTTP $statusCode)"
        }
    }
    Start-Sleep -Milliseconds 300
}

# ============================================================================
# TEST 7: IDEMPOTENCY
# ============================================================================
Write-Header "TEST 7: IDEMPOTENCY - NO DOUBLE CHARGES"

Write-Step "Send same authorize request twice with same idempotency key"
try {
    $iKey = New-IKey
    $iBody = @{
        payment_id      = "pi_idem_$(Get-Date -Format 'yyyyMMddHHmmss')"
        merchant_id     = "m_123"
        amount          = 3000
        currency        = "usd"
        idempotency_key = $iKey
        card            = @{
            number    = "4242424242424242"
            exp_month = 12
            exp_year  = 2026
            cvc       = "123"
        }
    } | ConvertTo-Json

    $first = Invoke-RestMethod -Uri "$BANK_CONNECTOR/authorize" `
        -Method POST -Body $iBody -ContentType "application/json"

    Start-Sleep -Seconds 1

    $second = Invoke-RestMethod -Uri "$BANK_CONNECTOR/authorize" `
        -Method POST -Body $iBody -ContentType "application/json"

    if ($first.processor_id -eq $second.processor_id) {
        Pass "Idempotency working correctly"
        Info "Both requests returned same processor ID"
        Info "Processor ID: $($first.processor_id)"
        Info "Second idempotent: $($second.raw_response.idempotent)"
    } else {
        Fail "Different processor IDs - double charge risk!"
        Info "First:  $($first.processor_id)"
        Info "Second: $($second.processor_id)"
    }
} catch {
    $e = Get-ErrorDetail $_
    Fail "Idempotency test failed"
    Info "Error: $($e.detail)"
}

