# ============================================================================
# TEST 15: FULL CUSTOMER FLOW
# ============================================================================
Write-Header "TEST 15: FULL CUSTOMER FLOW (Session → Token → Confirm)"

Write-Step "Step 1: Get JWT token"
try {
    $jwt = (Invoke-RestMethod -Uri "$AUTH_SERVICE/token" -Method POST `
        -Body (@{
            sub    = "cust_bc_$(Get-Date -Format 'yyyyMMddHHmmss')"
            email  = "customer@gmail.com"
            roles  = @("customer")
            scopes = @(
                "payment_session:create"
                "payment_session:read_own"
                "payment_method:tokenize"
                "payment_intent:confirm_own"
                "public_config:read"
            )
        } | ConvertTo-Json) -ContentType "application/json").access_token

    Pass "JWT token obtained"
    Info "Token: $($jwt.Substring(0,50))..."
} catch {
    Fail "JWT failed" $_
    exit 1
}

$cHeaders = @{
    "Content-Type"      = "application/json"
    "X-Publishable-Key" = $PUBLISHABLE_KEY
    "Authorization"     = "Bearer $jwt"
}

Write-Step "Step 2: Create payment session (\$99)"
try {
    $session = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/customer/payment_sessions" `
        -Method POST -Headers $cHeaders `
        -Body (@{
            cart_id     = "cart_bc_$(Get-Date -Format 'yyyyMMddHHmmssff')"
            order_id    = "order_bc_$(Get-Date -Format 'yyyyMMddHHmmssff')"
            amount      = 9900
            currency    = "usd"
            description = "Customer bank connector test - \$99"
            metadata    = @{ test="bank_connector_e2e" }
            capture     = $true
        } | ConvertTo-Json)

    Pass "Session created"
    Info "Session ID: $($session.session_id)"
    Info "Amount: `$$($session.amount/100)"
    Info "Status: $($session.status)"
    Info "Expires: $($session.expires_at)"
} catch {
    $e = Get-ErrorDetail $_
    Fail "Session creation failed"
    Info "Error: $($e.detail)"
    exit 1
}

Write-Step "Step 3: Tokenize Mastercard"
try {
    $token = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/customer/payment_methods/tokenize" `
        -Method POST -Headers $cHeaders `
        -Body (@{
            card_number = "5555555555554444"
            exp_month   = 12
            exp_year    = 2026
            cvc         = "123"
        } | ConvertTo-Json)

    Pass "Card tokenized"
    Info "Token: $($token.payment_method_token)"
    Info "Brand: $($token.brand) | Last4: $($token.last4)"
    Info "Status: $($token.status)"
    Info "Expires: $($token.expires_at)"
} catch {
    $e = Get-ErrorDetail $_
    Fail "Tokenization failed"
    Info "Error: $($e.detail)"
    exit 1
}

Write-Step "Step 4: Confirm payment"
try {
    $payment = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/customer/payment_intents/confirm" `
        -Method POST -Headers $cHeaders `
        -Body (@{
            session_id           = $session.session_id
            payment_method_token = $token.payment_method_token
        } | ConvertTo-Json)

    $script:C_PAYMENT_ID = $payment.payment.payment_id

    Pass "Customer payment confirmed!"
    Info "Payment ID: $($payment.payment.payment_id)"
    Info "Status: $($payment.payment.status)"
    Info "Amount: `$$($payment.payment.amount/100)"
    Info "Captured: `$$($payment.payment.amount_captured/100)"
    Info "Card: $($payment.payment.card_brand) **** $($payment.payment.card_last4)"
    Info "Auth Code: $($payment.payment.authorization_code)"
    Info "Session Status: $($payment.session.status)"
    Info "Confirmed At: $($payment.session.confirmed_at)"
} catch {
    $rawErr = $_.ErrorDetails.Message
    Fail "Customer payment failed"
    try {
        $e = $rawErr | ConvertFrom-Json
        Info "Code: $($e.detail.code)"
        Info "Message: $($e.detail.message)"
        Info "Risk Score: $($e.detail.risk_score)"
        if ($e.detail.code -eq "fraud_detected") {
            Info "→ Fraud service blocked it (velocity/risk)"
            Info "→ Run: docker exec postgres psql -U payments -d fraud_db -c 'TRUNCATE fraud_checks, ml_training_samples CASCADE;'"
        }
    } catch {
        Info "Raw error: $rawErr"
    }
}

# ============================================================================
# TEST 16: CUSTOMER FLOW - DECLINED CARD
# ============================================================================
Write-Header "TEST 16: CUSTOMER FLOW - DECLINED CARD"

Write-Step "Customer tries to pay with declined card"
try {
    $declineSession = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/customer/payment_sessions" `
        -Method POST -Headers $cHeaders `
        -Body (@{
            cart_id  = "cart_dec_$(Get-Date -Format 'yyyyMMddHHmmssff')"
            amount   = 3000
            currency = "usd"
            capture  = $true
        } | ConvertTo-Json)

    $declineToken = Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/customer/payment_methods/tokenize" `
        -Method POST -Headers $cHeaders `
        -Body (@{
            card_number = "4000000000000002"
            exp_month   = 12
            exp_year    = 2026
            cvc         = "123"
        } | ConvertTo-Json)

    Invoke-RestMethod `
        -Uri "$API_GATEWAY/v1/customer/payment_intents/confirm" `
        -Method POST -Headers $cHeaders `
        -Body (@{
            session_id           = $declineSession.session_id
            payment_method_token = $declineToken.payment_method_token
        } | ConvertTo-Json)

    Fail "Should have been declined!"
} catch {
    $statusCode = $_.Exception.Response.StatusCode.value__
    if ($statusCode -eq 402) {
        Pass "Customer declined card handled correctly (402)"
        try {
            $e = $_.ErrorDetails.Message | ConvertFrom-Json
            Info "Error: $($e.detail)"
        } catch {}
    } else {
        Pass "Customer declined card rejected (HTTP $statusCode)"
    }
}

# ============================================================================
# TEST 17: IDEMPOTENCY - MERCHANT
# ============================================================================
Write-Header "TEST 17: MERCHANT IDEMPOTENCY"

Write-Step "Same merchant payment twice with same idempotency key"
try {
    $iKey = New-IKey
    $iHeaders = @{
        "Content-Type"    = "application/json"
        "Authorization"   = "Bearer $SECRET_KEY"
        "Idempotency-Key" = $iKey
    }
    $iBody = @{
        amount   = 4000
        currency = "usd"
        customer = @{ email="idem@example.com"; name="Idem Test" }
        card     = @{ number="4242424242424242"; exp_month=12; exp_year=2026; cvc="123" }
        capture  = $false
    } | ConvertTo-Json

    $first = Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $iHeaders -Body $iBody
    Start-Sleep -Seconds 1
    $second = Invoke-RestMethod -Uri "$API_GATEWAY/v1/merchant/payment_intents" `
        -Method POST -Headers $iHeaders -Body $iBody

    if ($first.payment_id -eq $second.payment_id) {
        Pass "Merchant idempotency working"
        Info "Both returned same payment ID: $($first.payment_id)"
    } else {
        Fail "Different payment IDs returned!"
        Info "First: $($first.payment_id)"
        Info "Second: $($second.payment_id)"
    }
} catch {
    Fail "Idempotency test failed" $_
}

# ============================================================================
# TEST 18: FINAL STATS
# ============================================================================
Write-Header "TEST 18: FINAL STATS"

Write-Step "Bank Connector final stats"
try {
    $finalStats = Invoke-RestMethod -Uri "$BANK_CONNECTOR/stats" -Method GET
    Pass "Final stats retrieved"
    Info "Total Transactions: $($finalStats.total_transactions)"
    Info "Successful: $($finalStats.successful)"
    Info "Failed: $($finalStats.failed)"
    Info "Success Rate: $($finalStats.success_rate)%"
    foreach ($cb in $finalStats.circuit_breakers.PSObject.Properties) {
        Info "Circuit Breaker [$($cb.Name)]: $($cb.Value.state)"
    }
} catch {
