}

Write-Step "Fraud Service final stats"
try {
    $fraudStats = Invoke-RestMethod -Uri "$FRAUD_SERVICE/stats" -Method GET
    Pass "Fraud stats retrieved"
    Info "Total Checks: $($fraudStats.total_checks)"
    Info "Allowed: $($fraudStats.allowed)"
    Info "Blocked: $($fraudStats.blocked)"
    Info "Block Rate: $($fraudStats.block_rate)%"
} catch {
    Warn "Could not retrieve fraud stats"
}

